def mutate_gene(self, gene_name, current_value, possible_values):
    if possible_values:
        choices = list(set(possible_values) - set([current_value]))
        if choices:
            mutation_probability = self.mutation_rate * 3  # Increase mutation probability further
            if random.random() < mutation_probability:
                # Force exploration by choosing a random value even if it's similar to current
                return random.choice(choices)
        else:
            # If no other choices available, slightly alter the current value
            mutation_probability = self.mutation_rate
            if random.random() < mutation_probability:
                # Increment/decrement current value within bounds
                step = random.randint(-1, 1)
                new_value = current_value + step
                # Clamp new value within search space range
                lower_bound = min(self.search_space[gene_name])
                upper_bound = max(self.search_space[gene_name])
                return max(lower_bound, min(new_value, upper_bound))
